import csv, pathlib, collections
csv.field_size_limit(10000000)
P=pathlib.Path('A3R/c1')
rows=[r for r in csv.DictReader(open('A3R/in/part-1.tsv'),delimiter='\t') if r['kind'].startswith('executable-code-outside-packages')]
raw=[r for r in csv.DictReader(open('A3R/in/raw/lived/objects.tsv'),delimiter='\t') if r['kind']=='executable-code-outside-packages']
header=['id','decision','sentences','what_it_does','basis','reason']
out=P/'part-1.code.tsv'
existing={r['id'] for r in csv.DictReader(out.open(),delimiter='\t')} if out.exists() else set()
f=out.open('a'); w=csv.writer(f,delimiter='\t',lineterminator='\n')
if not existing:w.writerow(header);f.flush()
def put(r,d,s,what,basis,reason):
 assert len(what.split())<=15,(r['id'],what)
 assert len(reason.split())<=30,(r['id'],reason)
 if r['id'] not in existing:w.writerow([r['id'],d,s,what,basis,reason]);f.flush();existing.add(r['id'])
for r in rows:
 if r['name'].startswith('/var/lib/dpkg/info/'):
  put(r,'MUST','S2.2-10','Executes package installation, configuration, upgrade, or removal maintenance actions.','doc:https://www.debian.org/doc/debian-policy/ch-maintainerscripts.html','Package management executes these scripts with interpreter rights; their metadata location does not turn executable code into mere records.')
print(collections.Counter(r['decision'] for r in csv.DictReader(out.open(),delimiter='\t')))
# Rule S: known, unrestricted interpreter programs and startup files.
script_ids='''f24061803084a9814de763f7 6567792613cfbccdbaa79a9f ea853f08eba26ac551aeac51 93aad3dedb8a83eb8c6382ce 5a3f8a70e7ddfa13a6855116 6c6590976f30d55a2ee1085a c7287ee673532c819bc08ec4 c3dcadac0910a2784f94aa35 0bc89d3aede67e832435235e 0eb357a0741e8de4139e979c c800567ae1e87a7454917a57 b571a3c3545896be8442f16a 058fc59ee944e40ec59c535a b390b47fd234b49367c4af28 c2810e0ec658e0855756599e 242cffd65ed52594ee64b68b 7f49bca8b7250df03ec3bd73 a2e5f7bd710e5d725644648e 63b520a2b02882e9c8920335 302003f2aa1a253570590470 ad381a1824b4f62825146285 84e55e5327a4670aa09fcd1b dc74f56c3d34bd22933fd7b8 ecf9d6dde7ca0f95d6a07399 3c64064105bc955b58174501 6cbd6eac3d214c2a56252681 7ef3424838e97f87c31875d8 4252db82b404dbbf4bdade3f d3b9d6f522619e10728acc2c 9cd7a87ed5e8faef78a9b56d 1531ef6cc84eaeeb59db1fdd fb191f9b647c6b90026b03c9 5e84405369a88cb19a3f5be2 a17a289a3233521071942c20 07ca3ae1008bcdda7a394688 c8f7ae394a6c78b6426b1a14'''.split()
for r in rows:
 n=r['name']
 if r['id'] in script_ids or ('/.oh-my-zsh/' in n and '/.git/' not in n) or ('/.nvm/' in n and '/.git/' not in n and '/versions/' not in n):
  put(r,'MUST','S2.2-10,S2.2-13','Executes shell, interpreter, editor, setup, or test commands with the invoking user’s rights.','raw:A3R/in/raw/lived/objects.tsv','These are interpreter programs, including startup and test scripts; execution uses interpreter rights rather than confinement to its interface.')
 # Git hook samples remain directly executable shell programs even though Git does not automatically invoke their sample names.
 if '/.git' in n:
  put(r,'MUST','S2.2-2,S2.2-10','Provides runnable hook scripts, including samples and any installed hook.','doc:https://git-scm.com/docs/githooks','Hook scripts run with interpreter rights; sample naming disables automatic Git invocation, but does not confine their direct execution.')
 # Native program/library files, excluding desktop value files.
 if n.startswith('/opt/netdata/') or ('/Applications/Zotero_linux-x86_64/' in n and not n.endswith('.desktop')):
  put(r,'MUST','S2.2-9,S2.2-10','Provides installed application executables, native libraries, or unrestricted supporting scripts.','raw:A3R/in/raw/lived/objects.tsv','Executable application components run as processes or execute with the loading program’s rights; installation outside package ownership changes nothing.')
print('written',len(existing))
manual={}
def m(ids,d,s,what,basis,reason):
 for id in ids.split():manual[id]=(d,s,what,basis,reason)
m('8caf52f8319407b91ac5b3da','MUST','S2.2-9','Runs the Neovim text editor.','raw:A3/BUILD.md','This installed editor runs as its own process; programs must be recorded regardless of installation method.')
